OUT_DIR = pathlib.Path(__file__).resolve().parent.parent / "prblm_mailer/static/prblm_mailer/icons"
# 64px source for an 18-34px display: retina-sharp, and still ~4KB per file.
SIZE = 64
VARIANTS = {"white": "#ffffff", "dark": "#1f2124"}


def main():
    import cairosvg

    missing = set(PLATFORMS) ^ set(PATHS)
    if missing:
        raise SystemExit(f"social.py and PATHS disagree about: {sorted(missing)}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for slug, (view_box, path) in PATHS.items():
        for variant, fill in VARIANTS.items():
            svg = (
                f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view_box}">'
                f'<path fill="{fill}" d="{path}"/></svg>'
            ).encode()
            cairosvg.svg2png(bytestring=svg, write_to=str(OUT_DIR / f"{slug}-{variant}.png"),
                             output_width=SIZE, output_height=SIZE)
    print(f"Wrote {len(PATHS) * len(VARIANTS)} PNGs for {len(PATHS)} platforms to {OUT_DIR}")


if __name__ == "__main__":
    main()
